export default function Home() {
  return (
    <>
      <h1>Roster is an agent that runs performance reviews for a team&apos;s AI coding agents.</h1>
      <p className="lede">
        It reads every session your coding agents recorded with Entire and works out what each
        session cost, and whether its change survived, was reverted, or was reworked by a human.
      </p>
      {/* TODO: link target is a placeholder until our own review is published. */}
      <p>
        <a href="/r/_sample/_sample">See an example review (sample data) →</a>
      </p>
    </>
  );
}
import type { Metadata, Viewport } from "next";
import { Inter, JetBrains_Mono } from "next/font/google";
import "./globals.css";

const inter = Inter({ subsets: ["latin"], variable: "--font-inter", display: "swap" });
const mono = JetBrains_Mono({ subsets: ["latin"], variable: "--font-mono", display: "swap" });

export const metadata: Metadata = {
  title: "Roster",
  description: "Performance reviews for AI coding agents.",
};

export const viewport: Viewport = { width: "device-width", initialScale: 1, colorScheme: "dark" };

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" className={`${inter.variable} ${mono.variable}`}>
      <body>
        <header className="top">
          <a href="/" className="brand">roster</a>
        </header>
        <main>{children}</main>
      </body>
    </html>
  );
}
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import type { Review, SetupRow } from "./types";

const DATA = join(process.cwd(), "public", "data");

function readReview(dir: string): Review | null {
  const file = join(DATA, dir, "review.json");
  if (!existsSync(file)) return null;
  try {
    return normalize(JSON.parse(readFileSync(file, "utf8")));
  } catch {
    return null;
  }
}

/**
 * Accepts a review.json as `roster review` writes it. Files that are not reviews (no repo or setups) give null.
 * Older files without mature_sessions or cost_per_surviving_change get those filled in; rows with no mature
 * session have every rate nulled so the page never shows 0% for a setup that has no scored work.
 */
function normalize(raw: unknown): Review | null {
  if (typeof raw !== "object" || raw === null) return null;
  const r = raw as Partial<Review>;
  if (typeof r.repo !== "string" || !Array.isArray(r.setups)) return null;
  const setups = r.setups.map((s): SetupRow => {
    const mature = s.mature_sessions ?? s.sessions;
    const young = mature === 0;
    return {
      ...s,
      mature_sessions: mature,
      unattended: young ? null : s.unattended,
      survival: young ? null : s.survival,
      reverted: young ? null : s.reverted,
      rework_human: young ? null : s.rework_human,
      cost_per_surviving_change: s.cost_per_surviving_change ?? null,
    };
  });
  return { ...(r as Review), setups };
}

/** True for a setup with no mature session: its rates are null and should read "too young", not 0%. */
export const isTooYoung = (s: SetupRow) => s.mature_sessions === 0;

/** Slug dirs tried in order: "_sample", "owner__repo", "owner-repo", "owner/repo". */
function candidates(owner: string, repo: string): string[] {
  const list = [`${owner}__${repo}`, `${owner}-${repo}`, join(owner, repo)];
  if (owner === "_sample" && repo === "_sample") list.unshift("_sample");
  return list;
}

export function loadReview(owner: string, repo: string): Review | null {
  for (const c of candidates(owner, repo)) {
    const r = readReview(c);
    if (r) return r;
  }
  return null;
}

export function listParams(): { owner: string; repo: string }[] {
  if (!existsSync(DATA)) return [];
  const out: { owner: string; repo: string }[] = [];
  for (const d of readdirSync(DATA, { withFileTypes: true })) {
    if (!d.isDirectory()) continue;
    const r = readReview(d.name);
    if (r) {
      const [owner, repo] = r.repo.split("/");
      if (owner && repo) out.push({ owner, repo });
    }
  }
  return out;
}
// Local copy of the review shape (web/ must build without ../src). Mirrors SetupRow, ReviewTags and Review
// in src/types.ts; keep the two in step. Rates are fractions in [0, 1] over mature sessions, or null.

export type EvidenceLevel = "A" | "B" | "C";
export type ReviewLabel = "suspect" | "no_suspect" | "insufficient_data";

export interface SetupRow {
  setup_id: string;
  label: string;
  harness: string;
  model: string;
  rules_hash: string | null;
  sessions: number;
  mature_sessions: number;
  /** null when any session in the setup is unpriced. */
  spend_usd: number | null;
  /** Absent in reviews published before T40. */
  priced_sessions?: number;
  /** Absent in reviews published before T40. */
  spend_lower_bound?: boolean;
  unattended: number | null;
  survival: number | null;
  reverted: number | null;
  rework_human: number | null;
  surviving_changes: number;
  cost_per_surviving_change: number | null;
  evidence_level: EvidenceLevel;
}

export interface ReviewTags {
  by_tag: Record<string, { sessions: number; setup_ids: string[] }>;
  tag_accuracy: number | null;
}

export interface Review {
  id: string;
  repo: string; // "owner/name"
  created_at: string;
  generated_at: string; // ISO timestamp
  has_entire_data: boolean;
  setups: SetupRow[];
  tags?: ReviewTags;
  label: ReviewLabel;
  suspect: string | null;
  odds_ratio: number | null;
  ci95: [number, number] | null;
  p_value: number | null;
  evidence_level: EvidenceLevel;
  /** Only the checked-in layout sample sets this. */
  sample?: boolean;
}
